<?php
$addressCatalog=\App\AddressService::catalog();$addressAvailable=(bool)$addressCatalog;
$townDirectoryReady=\App\TownService::ready();$addressCatalog=$addressCatalog?:['regions'=>[],'districts'=>[],'towns'=>[]];
$townChoice=$values['town_choice']??(!empty($values['town'])?'new':'');$scopedTowns=[];
foreach($addressCatalog['towns']??[] as $townItem){
 if(($townItem['region_name']??'')!==($values['residential_region']??'')||($townItem['district_name']??'')!==($values['residential_district']??'')){continue;}
 $scopedTowns[]=$townItem;
 if(!array_key_exists('town_choice',$values)&&mb_strtolower($townItem['name'])===mb_strtolower(trim($values['town']??''))){$townChoice=(string)$townItem['id'];}
}
?>
<div class="col-12"><h2 class="h5">Residential address <span class="small text-secondary fw-normal">Optional</span></h2><p class="text-secondary">Select a residential region and district, then search for a town or choose a popular town below.</p></div>
<div class="col-12"><?= input('address','Address / house or street',$values['address']??'','text',false,'maxlength="1000" autocomplete="address-line1"') ?></div>
<?php if(!$addressAvailable): ?><div class="col-12"><div class="alert alert-info">Complete migrations 09 and 10 in phpMyAdmin to enable these residential dropdowns. Your street address can still be saved.</div></div><?php endif; ?>
<div class="col-12"><div class="row g-3" data-address-picker data-town-directory-ready="<?= $townDirectoryReady?'1':'0' ?>" data-address-catalog="<?= e(json_encode($addressCatalog,JSON_THROW_ON_ERROR)) ?>">
<div class="col-md-4"><label class="form-label" for="residential-region">Residential region</label><select class="form-select" id="residential-region" name="residential_region" data-address-region <?= !$addressAvailable?'disabled':'' ?>><option value="">Not assigned</option><?php foreach($addressCatalog['regions'] as $regionItem): ?><option value="<?= e($regionItem['name']) ?>" <?= ($values['residential_region']??'')===$regionItem['name']?'selected':'' ?>><?= e($regionItem['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label" for="residential-district">Residential district</label><select class="form-select" id="residential-district" name="residential_district" data-address-district <?= !$addressAvailable?'disabled':'' ?>><option value="">Not assigned</option><?php foreach($addressCatalog['districts'] as $districtItem): if($districtItem['region_name']!==($values['residential_region']??'')){continue;} ?><option value="<?= e($districtItem['name']) ?>" <?= ($values['residential_district']??'')===$districtItem['name']?'selected':'' ?>><?= e($districtItem['name']) ?></option><?php endforeach; ?></select><p class="form-text">Select a region to load its districts.</p></div>
<div class="col-md-4"><label class="form-label" for="residential-town-choice">Residential town</label><select class="form-select" id="residential-town-choice" name="town_choice" data-town-choice <?= !$addressAvailable?'disabled':'' ?>><option value="">Not assigned</option><?php if($townChoice==='new'): ?><option value="new" selected><?= e($values['town']??'') ?></option><?php endif; ?><?php foreach($scopedTowns as $townItem): ?><option value="<?= e($townItem['id']) ?>" <?= $townChoice===(string)$townItem['id']?'selected':'' ?>><?= e($townItem['name']) ?></option><?php endforeach; ?></select>
<input type="hidden" name="town" value="<?= e($values['town']??'') ?>" data-address-town><p class="small text-secondary mt-2 mb-0" id="residential-town-status" data-town-status role="status" aria-live="polite">Type to find a saved town. Add a town appears only when no matching name is found.</p></div>
<div class="col-12"><div class="small fw-semibold mb-2">Popular towns in the selected district</div><div class="d-flex flex-wrap align-items-center gap-2" data-popular-towns></div><p class="form-text" data-popular-town-status role="status">Select a district to see its popular towns.</p></div><div class="col-12"><p class="small text-secondary">These dropdowns use the residential directories. Electoral region, constituency and polling station remain separate.</p><?php if(\App\Auth::canManage()): ?><div class="d-flex flex-wrap gap-3 small"><a href="<?= e(url('residential_regions')) ?>">Residential regions</a><a href="<?= e(url('districts')) ?>">Districts</a><a href="<?= e(url('residential_towns')) ?>">Saved towns</a></div><?php endif; ?>
<?php if($addressAvailable&&!$townDirectoryReady): ?><p class="small text-secondary mt-2">Import database/12_residential_towns_mysql8.sql in phpMyAdmin to enable saved towns. Until then, type a town name to save town text.</p><?php endif; ?>
<?php if($addressAvailable&&!$addressCatalog['regions']): ?><p class="small text-secondary mt-2">No residential regions found. Add your regions and districts using the links above.</p><?php endif; ?></div></div></div>
